content.query:
let inputPrice = todouble("{InputPricePerMillion}") / 1000000.0;
let outputPrice = todouble("{OutputPricePerMillion}") / 1000000.0;
let tokens = customMetrics
| where name == "gen_ai.client.token.usage"
| extend tokenType = tostring(customDimensions["gen_ai.token.type"])
| summarize inputTokens = sumif(valueSum, tokenType == "input"), outputTokens = sumif(valueSum, tokenType == "output");
let claims = toscalar(customMetrics | where name == "claims.intake" | extend outcome = tostring(customDimensions["outcome"]) | where outcome == "accepted" | summarize sum(value));
tokens
| extend costGbp = inputTokens * inputPrice + outputTokens * outputPrice, claims = claims
| extend gbpPerClaim = iff(claims > 0, costGbp / claims, real(null))
| project inputTokens, outputTokens, costGbp, claims, gbpPerClaim
